export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:00。M 區。指揮走廊。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "桌面被清空過一次。現在又排滿了。不是證物袋——是文件夾。舊的。封面發黃。邊角有水漬。像從一個很久沒有人打開的櫃子裡取出來的。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部坐在桌前。他面前放著一個硬殼文件夾。封面貼著編號標籤。標籤上印著——", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "`KAGAMI-SAFE`", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯KAGAMI-SAFE。⋯⋯爸爸的。七年前的。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "內部監察封緘，國安移交索引保留，頁數、附件名、文件雜湊都有。今天只有限解封。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "有限？", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "只開跟紗英拘束、悠真安否、當輪 TOKYO 公共風險直接相關的頁面。國際資料、其他受試者、你父親完整去向——仍封緘。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯爸爸的完整去向。⋯⋯仍封緘。⋯⋯他到過 M 區外第一道門。報告被國安接管。之後從普通行政紀錄消失。⋯⋯現在他在哪裡——不知道。⋯⋯先不看那個。先看打開的。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部打開文件夾。裡面是列印件。紙張很薄。字體是舊式的。像用十年前的文書系統排的。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "首頁。報告名稱。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "KAGAMI-SAFE 斜線 R1。M-00 外部醫療移管及鏡島放大節點安全切離案。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到第二頁。第三頁。第四頁。每一頁的右下角都有手寫簽名。朝倉源一郎。澪認得那個字跡。很小。很密。像在節省紙。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯爸爸的字。⋯⋯七年了。⋯⋯他寫的時候——是什麼時候。什麼狀態。他知道嗎。他知道裡面那個人是媽媽嗎。⋯⋯他知道。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家坐在桌子的另一端。他面前放著一台筆電。螢幕上是文件雜湊比對工具。他正在核對封緘件的數位指紋。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R1 雜湊與國安移交索引一致。封緘狀態確認。未遭篡改。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "五項原則。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到第五頁。標題是手寫的。字很小。旁邊有紅筆畫的線。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一。醫療與校準分離。M-00 的醫療維持與訊號校準必須先拆開。不能一起關。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第二。所有活動接收者撤離以前，不得執行硬切。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的手指停在那一行上。停了一秒。然後繼續。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第三。不得以一名新接收者永久替代另一名接收者。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第四。切離前必須將交通、警報、研究、醫療及門禁原始紀錄置於外部司法控制。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第五。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他讀。聲音變平了。像在讀一條不可妥協的底線。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "無法安全切離時——不得啟動 TOKYO。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不得啟動 TOKYO。⋯⋯爸爸七年前就寫了這句。⋯⋯不是「小心啟動」。不是「評估後啟動」。是——不得啟動。⋯⋯如果無法安全切離。就不能啟動。⋯⋯可是下一個星期一——TOKYO-7 的排程還在那裡。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家在筆電上記錄了五項原則的頁碼和雜湊。他沒有評論。只確認。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R1 原則頁面雜湊與索引一致。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "日期。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到文件末頁。建立日期欄。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七年前四月。R1。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他從文件夾裡取出另一份。更薄。封面是另一種紙。更白。更硬。像技術規格書。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這份不是從舊案調出來的。是千田的律師今天送到的。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯千田。⋯⋯他還活著。這一輪他還活著。他的律師保留了正式附錄。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "KAGAMI-SAFE 斜線 R2。技術修訂附錄。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他打開。裡面是列印件。紙張更新。字體是工程規格的等寬字體。每一頁底部都有律師保全章和技術簽章。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不是獨立新計畫，依 R1 文件編號登錄，引用 R1 雜湊，有日期、技術簽章及律師保全副本。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七年前五月上旬。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯R1 是四月。R2 是五月上旬。⋯⋯爸爸先建了根文件。千田在幾週後提交了技術附錄。⋯⋯他們認識。他們合作過。⋯⋯爸爸要求千田只核對公共系統架構。不提供紗英完整身分。⋯⋯他在保護媽媽。即使在建立安全方案的時候——他也在保護她。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家接過 R2 副本。他翻到技術頁面。螢幕上打開了 R1 雜湊比對結果。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R2 引用 R1 雜湊。一致。附錄格式符合技術修訂規範。律師保全副本在場。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R2 的內容。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到第一個技術頁面。標題是——", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "鏡島節點。KAGAMI-01。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯KAGAMI-01。⋯⋯K-01。⋯⋯Chapter 14 的舊維護資料裡出現過。灣岸中繼。校準節點。那時候不知道 K 是什麼。⋯⋯Chapter 16 白光觀察的時候，維護車和人工島方向的活動跟 K-01 時段相符。⋯⋯Chapter 20 M-00 技術血統圖下游有一個被遮蔽的名稱。⋯⋯現在展開了。KAGAMI-01。⋯⋯爸爸用既有節點的俗稱建立了安全切離案。KAGAMI-SAFE。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R2 顯示 KAGAMI-01 具有獨立狀態。四階段。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他讀。像在讀一張狀態表。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一——PREP。預備。第二——CAL LOCK。校準鎖定。第三——CONSENSUS COMMIT。一致性提交。第四——PUBLIC FANOUT。公共輸出。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "安全切離必須在 CONSENSUS COMMIT 前隔離一致性層。保留原始訊號過濾。維持 M-00 醫療支持。另行阻斷公共 fanout。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不是一個開關。是四個階段。⋯⋯要在第三階段之前隔離一致性層。要保留原始過濾。要維持醫療。要另外阻斷公共輸出。⋯⋯四件事。分開做。⋯⋯不能一起關。爸爸在 R1 就寫了——醫療與校準分離。千田在 R2 把它變成了技術步驟。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "COMMIT-GATE。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到下一頁。圖表。流程。節點之間的箭頭。其中一個被紅筆圈起來。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "與公共輸出分離的提交閘門。COMMIT-GATE。真正安全切離由 COMMIT-GATE 及放大節點狀態決定。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "COMMIT-GATE 是獨立於公共 fanout 的提交控制節點。它的狀態決定系統是否已經完成最終提交。不是倒數。不是時間鎖。是狀態判讀。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "七秒呢。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看了她一眼。然後翻到 R2 的下一節。標題是——`+7000ms 補正用途`。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七秒。三個用途。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一——配置指紋。當公共提示順序與七秒補正一致時，可辨認正在運作的是特定 TOKYO-7 多通道設定。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第二——最後手機路徑封鎖。在手機推送真正送出前，可取消最後一條應用推送。可保全尚未送出的 payload。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第三——提交狀態診斷。七秒期間的通道回饋可判讀某些提交鎖是否已完成。系統是否仍只處於 staged 或 prepared。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了。翻到下一頁。標題是——`+7000ms 不可用於`。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七秒不能——撤回已播出的廣播。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不能被當成整套系統的硬切倒數。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不能取代 COMMIT-GATE 的真正安全狀態判讀。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯七秒。⋯⋯Chapter 14 的時候我以為七秒只是手機應用的伺服器發送補正。⋯⋯它確實是。可是 R2 把它變成了工具。⋯⋯配置指紋。手機路徑封鎖。提交診斷。⋯⋯三個用途。全部是診斷和封鎖。沒有一個是「切斷系統」。⋯⋯七秒不是倒數。不是開關。不能撤回已經播出的東西。不能取代 COMMIT-GATE。⋯⋯真正的安全切離——要看 COMMIT-GATE。要看 KAGAMI-01 的四階段狀態。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家在筆電上記錄了七秒的三項可用用途和三項不可用邊界。他沒有評論。只確認。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R2 七秒邊界與 Chapter 14 已鎖定的 `+7000ms` 伺服器補正一致。用途限定與技術附錄相符。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R2 還有離線設定載體。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到下一節。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "原始訊號過濾、一致性層與公共 fanout 可分段隔離。離線設定載體用於保存預簽署套件。不依賴遠端帳號。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯離線載體。⋯⋯不依賴遠端帳號。⋯⋯這就是為什麼——即使凍結了遠端部署——本地仍然可能有東西能重新啟動。⋯⋯Chapter 18 的維護窗口。那枚封緘物件。⋯⋯先記下來。先記下來。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:14。日下部合上 R2。他從文件夾底部取出一張更舊的紙。不是列印件。是手寫的。紙張更薄。邊角有摺痕。像被折過放進口袋裡很久。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R3。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯R3。⋯⋯不是列印件。是手寫的。⋯⋯誰的？", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "紗英的臨床安全紀錄。較早期。父親後來納入同一案件編號。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有翻開。他只展示了索引頁——上面有文件名、日期、轉錄者簽名和雜湊。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R3 正文仍不完整。當輪只有——文件索引與雜湊。R1 的三段引用。臨床實施檢查表。紗英當輪的低負荷確認。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七年前五月下旬。父親將較早期的紗英臨床安全紀錄納入版本鏈。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯R1 是四月。R2 是五月上旬。R3 是五月下旬。⋯⋯可是 R3 的內容來源比 R1 更早。⋯⋯紗英在間歇清醒期留下臨床安全短語和眼動紀錄。具名醫療記錄員轉錄。爸爸發現後——把它納入 KAGAMI-SAFE 的版本鏈。⋯⋯內容早於 R1。納入版本晚於 R2。⋯⋯所以版本順序是 R1、R2、R3。可是內容順序是 R3 的來源最早。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家在筆電上排列了三個版本。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "版本時間表。R1 是七年前四月，父親建立根文件與安全原則。R2 是七年前五月上旬，千田依 R1 文件號提交技術附錄。R3 是七年前五月下旬，父親將較早期紗英臨床安全紀錄納入版本鏈。七年前六月後版本鏈停止，父親失蹤，R1 至 R3 未完成正式演練。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停下來。看了一眼螢幕。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R3 內容來源早於 R1。納入版本晚於 R2。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "R1 引用 R3 的部分呢。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "三段。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻回 R1。找到標記過的段落。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一——完整未成立未來方案會增加來源混淆。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第二——每輪必須重新驗證。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第三——託管回聲只應攜帶必要安全錨點。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯託管回聲。⋯⋯R3 在講——記憶。不是普通的記憶。是從未來送回來的記憶。⋯⋯爸爸七年前的文件裡——已經在討論這件事。⋯⋯他知道的比我想像的多。⋯⋯可是他沒有寫完。六月之後——版本鏈停止。他消失了。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部合上文件夾。他的手指在封面上停了一下。封面上的字——`KAGAMI-SAFE`——被他的拇指輕輕壓過。像在確認它是真的。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "父親完成 R1。到過 M 區外第一道門。報告被國安接管。之後從普通行政紀錄消失。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯他在哪裡。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不知道。今天不解封那一部分。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不知道。⋯⋯爸爸。⋯⋯你七年前的文件還在。你的字跡還在。可是你不在。⋯⋯你寫了不得啟動 TOKYO。你寫了先撤離接收者。你寫了不得以新受試者替代。⋯⋯你把安全方案留下了。然後你消失了。⋯⋯為什麼。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:05。文件暫時封回。指定專家保存雜湊紀錄和比對結果。律師保全副本由獨立保管人簽收。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "桌面又空了。只剩下三個版本的名稱，寫在白板上。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "`KAGAMI-SAFE／R1`——七年前四月。父親。五項原則。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "`KAGAMI-SAFE／R2`——七年前五月上旬。千田。KAGAMI-01。COMMIT-GATE。七秒邊界。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "`KAGAMI-SAFE／R3`——七年前五月下旬。紗英臨床安全紀錄。索引與部分摘要。正文不完整。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯三個版本。三個人。⋯⋯爸爸建了框架。千田補了技術。紗英留下了臨床安全原則。⋯⋯他們沒有同桌制定計畫。他們各自貢獻了一部分。爸爸把它們放進同一個案件編號。⋯⋯然後鏈斷了。六月之後。爸爸消失。R1 到 R3 沒有完成正式演練。⋯⋯七年後——我在這裡。拿著他們留下的碎片。⋯⋯而下一個星期一——TOKYO-7 的排程還在那裡。M-00 校準。一致性層 armed。公共路徑 staged。⋯⋯爸爸說——無法安全切離時，不得啟動 TOKYO。⋯⋯現在呢。現在能安全切離嗎。⋯⋯我不知道。還不知道。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:22。日下部站起來。他把文件夾交給指定專家封存。他看了一眼觀察窗。窗後那個人還在呼吸。很慢。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "先吃飯。紗英和悠真要休息。下午繼續。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯好。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:30。走廊裡的人開始移動。有人在收文件。有人在收筆電。有人在換班。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪最後看了一眼白板。三個版本名稱。三個日期。三個人。一條斷掉的鏈。", background: Background.Chapter_21_Ch21_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯R1。R2。R3。⋯⋯沒有 R4。⋯⋯當輪沒有 R4。⋯⋯⋯⋯可是為什麼——⋯⋯我覺得缺的那一塊——⋯⋯不是別人沒寫完。⋯⋯是我。", background: Background.Chapter_21_Ch21_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約四日十六小時四十三分鐘。", background: Background.Chapter_21_Ch21_Act3_S0 },
];
